        db 1, $02, 20           ; right from (38, 38), 20 pixels
        dw $CC26
        db 1, $02, 20           ; right from (38, 57), 20 pixels
        dw $CF21
        db 4
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
